package org.schoolkernel.workspace;

import java.util.*;
import org.springframework.stereotype.Service;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.node.ArrayNode;
import tools.jackson.databind.node.ObjectNode;

/** Deterministic, read-only saved review. Potential timing uses Current placements, never a fabricated solve. */
@Service
public class DefinitionReviewService {
    private final ObjectMapper json;
    private final DefinitionEntityService entities;
    private final DefinitionGridService grid;
    public DefinitionReviewService(ObjectMapper json,DefinitionEntityService entities,DefinitionGridService grid){this.json=json;this.entities=entities;this.grid=grid;}
    public ObjectNode create(JsonNode savedDraft,long version){
        ObjectNode draft=((ObjectNode)savedDraft).deepCopy();entities.refreshAllEntityIssues(draft);grid.refreshIssues(draft);JsonNode source=DefinitionRemovalService.sourceDefinition(draft),definition=draft.path("definition");ObjectNode review=json.createObjectNode().put("version",version).put("draftRevision",draft.path("draftRevision").asString("")).put("sourceState",draft.path("sourceState").asString("")).put("sourceRevision",draft.path("sourceDocument").path("definitionRevision").asString(""));review.set("sourceIdentity",identity(source));review.set("draftIdentity",identity(definition));ArrayNode changes=review.putArray("changes");DefinitionComparison.compare(json,source,definition).forEach(changes::add);diffContext(changes,draft.path("sourceDocument").path("authoringContext"),draft.path("editingContext"));
        review.set("catalogUpgrades",draft.path("catalogUpgrades").isArray()?draft.path("catalogUpgrades"):json.createArrayNode());review.set("openingAdjustments",draft.path("openingAdjustments").isArray()?draft.path("openingAdjustments"):json.createArrayNode());review.set("expiredPins",draft.path("expiredPins").isArray()?draft.path("expiredPins"):json.createArrayNode());review.set("removedIdentities",draft.path("removedIdentities").isArray()?draft.path("removedIdentities"):json.createArrayNode());
        ArrayNode issues=review.putArray("issues");List<JsonNode> ordered=new ArrayList<>();draft.path("issues").forEach(ordered::add);ordered.sort(Comparator.comparing((JsonNode n)->n.path("severity").asString("").equals("BLOCKING")?0:1).thenComparing(n->n.path("ownerType").asString("")).thenComparing(n->n.path("ownerId").asString("")).thenComparing(n->n.path("field").asString("")).thenComparing(n->n.path("message").asString("")));
        for(JsonNode value:ordered){ObjectNode issue=(ObjectNode)value.deepCopy();ArrayNode related=issue.putArray("relatedLessonIds");String type=issue.path("ownerType").asString(""),id=issue.path("ownerId").asString(""),field=issue.path("field").asString("");for(JsonNode lesson:definition.path("lessons"))if(related(type,id,lesson,definition))related.add(lesson.path("id").asString(""));ArrayNode cause=issue.putArray("causalEdits");for(JsonNode change:changes)if(type.equals(change.path("ownerType").asString(""))&&id.equals(change.path("ownerId").asString(""))&&(field.equals(change.path("field").asString(""))||change.path("field").asString("").isEmpty()))cause.add(change.deepCopy());issues.add(issue);}
        ObjectNode counts=review.putObject("counts");counts.put("changes",changes.size()).put("blockers",issues.valueStream().filter(n->n.path("severity").asString("").equals("BLOCKING")).count()).put("advisories",issues.valueStream().filter(n->n.path("severity").asString("").equals("ADVISORY")).count()).put("lessons",definition.path("lessons").size());review.set("timingImpacts",timing(draft,definition));review.put("placementExplanation",draft.path("sourceDocument").has("acceptedBaseline")?"Potential successor timing at surviving Current placements; a repair proposal is required to determine actual placements. Period-ID/room moves are separate from weekday/order/time changes.":"No accepted source placements. No timetable placement is invented.");review.put("verificationExplanation","Definition verification is still required. No blocker does not establish timetable feasibility.");review.put("zeroLessonExplanation",definition.path("lessons").isEmpty()?"No lessons configured; planning will produce an empty timetable":"");return review;
    }
    private ObjectNode identity(JsonNode definition){ObjectNode identity=json.createObjectNode();for(String field:List.of("schoolId","displayName","schemaVersion","catalogVersion","basedOnRevision"))if(definition.has(field))identity.set(field,definition.path(field));return identity;}
    private void diffContext(ArrayNode changes,JsonNode before,JsonNode after){Set<String> keys=new TreeSet<>(before.propertyNames());keys.addAll(after.propertyNames());for(String key:keys){if(!Set.of("requirements","authoredLocks").contains(key)){diff(changes,"Editing context","",key,before.path(key),after.path(key));continue;}JsonNode old=before.path(key),next=after.path(key);Set<String> ids=new TreeSet<>(old.propertyNames());ids.addAll(next.propertyNames());for(String id:ids){JsonNode a=old.path(id),b=next.path(id);String type=key.equals("requirements")?"Requirement":"Lesson";if(a.isMissingNode()||b.isMissingNode()){diff(changes,type,id,"editingContext."+key,a,b);continue;}Set<String> fields=new TreeSet<>(a.propertyNames());fields.addAll(b.propertyNames());for(String field:fields)diff(changes,type,id,"editingContext."+key+"."+field,a.path(field),b.path(field));}}}
    private void diff(ArrayNode changes,String type,String id,String field,JsonNode before,JsonNode after){if(before.equals(after))return;ObjectNode row=changes.addObject().put("ownerType",type).put("ownerId",id).put("field",field).put("beforePresent",!before.isMissingNode()).put("afterPresent",!after.isMissingNode()).put("category",before.isMissingNode()?"Added":after.isMissingNode()?type.equals("Lesson")?"Cancelled":"Removed":"Changed");if(!before.isMissingNode())row.set("before",before.deepCopy());if(!after.isMissingNode())row.set("after",after.deepCopy());}
    private boolean related(String type,String id,JsonNode lesson,JsonNode definition){return switch(type){case "Lesson"->id.equals(lesson.path("id").asString(""));case "Teacher"->id.equals(lesson.path("teacherId").asString(""));case "Cohort"->id.equals(lesson.path("cohortId").asString(""));case "Subject"->id.equals(lesson.path("subjectId").asString(""));case "Requirement","Series"->id.equals(lesson.path("seriesId").asString(""));case "Room"->id.equals(lesson.path("roomLock").asString(""))||contains(lesson.path("preferredRoomIds"),id)||!lesson.path("requiredRoomCapabilityIds").isEmpty();case "Period"->id.equals(lesson.path("periodLock").asString(""))||contains(lesson.path("undesirablePeriodIds"),id);case "RoomAssignment"->{JsonNode policy=map(definition.path("roomAssignments"),"id").get(id);yield policy!=null&&policy.path("subjectId").equals(lesson.path("subjectId"))&&(!policy.has("teacherId")||policy.path("teacherId").equals(lesson.path("teacherId")));}case "School","Preference"->true;default->false;};}
    private ArrayNode timing(JsonNode draft,JsonNode definition){JsonNode baseline=draft.path("sourceDocument").path("acceptedBaseline");ArrayNode rows=json.createArrayNode();if(!baseline.isObject())return rows;Map<String,JsonNode> oldLessons=map(baseline.path("definition").path("lessons"),"id"),lessons=map(definition.path("lessons"),"id"),oldPeriods=map(baseline.path("definition").path("periods"),"id"),periods=map(definition.path("periods"),"id"),placements=map(baseline.path("result").path("timetable").path("assignments"),"lessonId");Set<String> ids=new TreeSet<>(oldLessons.keySet());ids.addAll(lessons.keySet());for(String id:ids){JsonNode placement=placements.get(id),old=placement==null?null:oldPeriods.get(placement.path("periodId").asString(""));JsonNode lesson=lessons.get(id);String potentialId=lesson!=null&&lesson.path("periodLock").isTextual()?lesson.path("periodLock").asString(""):placement==null?"":placement.path("periodId").asString("");JsonNode next=placement==null||lesson==null?null:periods.get(potentialId);boolean periodMove=placement!=null&&!potentialId.equals(placement.path("periodId").asString("")),roomMove=placement!=null&&lesson!=null&&lesson.has("roomLock")&&!lesson.path("roomLock").equals(placement.path("roomId"));boolean added=!oldLessons.containsKey(id),cancelled=!lessons.containsKey(id);if(!added&&!cancelled&&!periodMove&&!roomMove&&Objects.equals(timingFields(old),timingFields(next)))continue;ObjectNode row=rows.addObject().put("lessonId",id).put("displayName",lessons.getOrDefault(id,oldLessons.get(id)).path("displayName").asString(id)).put("kind",added?"Added — no accepted placement":cancelled?"Cancelled":next==null?"Current period removed — successor placement required":periodMove?"Potential period move required by authored lock":roomMove?"Potential room move required by authored lock":"Timing changed at same period ID");if(placement!=null)row.set("sourcePlacement",placement.deepCopy());if(old!=null)row.set("oldTiming",timingFields(old));if(next!=null){row.set("potentialTiming",timingFields(next));row.put("potentialPeriodId",potentialId);}row.put("periodIdMove",periodMove).put("roomMove",roomMove);if(lesson!=null&&lesson.has("roomLock"))row.set("potentialRoomId",lesson.path("roomLock"));}
        return rows;
    }
    private ObjectNode timingFields(JsonNode period){if(period==null)return null;ObjectNode result=json.createObjectNode();for(String field:List.of("weekday","order","startTime","endTime"))if(period.has(field))result.set(field,period.path(field));return result;}
    private static Map<String,JsonNode> map(JsonNode rows,String key){Map<String,JsonNode> result=new LinkedHashMap<>();for(JsonNode row:rows)result.put(row.path(key).asString(""),row);return result;}
    private static boolean contains(JsonNode rows,String id){for(JsonNode row:rows)if(id.equals(row.asString("")))return true;return false;}
}
